using System;
using NaughtyAttributes;

namespace Astrea.BattleActions;

[Serializable]
public class Rune : ActionFace
{
	[ShowIf("EnableSecondAction")]
	[AllowNesting]
	public BattleAction ReplacedBattleAction;

	public int index;

	public Rune(string FaceName, int ActionValue, BattleAction BattleAction, int index, BattleAction ReplacedBattleAction = null)
	{
		base.FaceName = FaceName;
		base.ActionValue = ActionValue;
		this.index = index;
		this.ReplacedBattleAction = ReplacedBattleAction;
		if (BattleAction != null)
		{
			base.BattleAction = BattleAction;
		}
	}
}
